export function getAvatarUrl(user) {
  if (!user) return '';
  if (user.avatarUrl && user.avatarUrl.trim()) return user.avatarUrl;
  const seed = encodeURIComponent(user.nickname || user.id || 'rrt');
  return `https://api.dicebear.com/7.x/bottts-neutral/svg?seed=${seed}&backgroundColor=6b7a37,8e2c20,c9a94a&radius=8`;
}

// ============================================================
//                  DISCORD WORKER — СОСТАВ
// ============================================================

const WORKER_URL = 'https://rrtauth.danikleprekon.workers.dev';
const ROSTER_CACHE_TTL = 60 * 1000;

function cleanNickname(raw) {
  if (!raw) return '';
  return raw
    .replace(/^\[RRT(-N)?\]\s*/i, '')
    .replace(/\s*\([^)]*\)\s*$/, '')
    .trim();
}

export async function fetchRoster(force = false) {
  if (!force) {
    try {
      const raw = localStorage.getItem(LS.rosterCache);
      if (raw) {
        const { ts, data } = JSON.parse(raw);
        if (Date.now() - ts < ROSTER_CACHE_TTL) return data;
      }
    } catch {}
  }

  const res = await fetch(WORKER_URL + '/api/roster');
  if (!res.ok) {
    const txt = await res.text();
    throw new Error(`Worker ${res.status}: ${txt}`);
  }
  const json = await res.json();
  const members = json.members || [];

  const users = members.map((m) => ({
    id: m.id,
    nickname: cleanNickname(m.name) || m.name,
    displayName: m.name,
    accessRole: roleKeyFromLevel(m.level) || 'recruit',
    level: m.level,
    topRole: (m.role_names && m.role_names[0]) || '',
    avatarUrl: m.avatar || '',
    joinedAt: (m.joined_at || '').slice(0, 10),
    birthDate: '',
    discordRoles: m.role_names || [],
    discordUsername: m.name,
    discordGlobalName: m.name,
    discordJoinedAt: (m.joined_at || '').slice(0, 10),
    discordBoostSince: '',
    discordPending: false,
  }));

  localStorage.setItem(LS.rosterCache, JSON.stringify({ ts: Date.now(), data: users }));
  return users;
}

